out=[];bad=0
for q,c,s,quote,niv,note in P:
    nq=norm(quote); hit=None
    for url,body in sorted(docs.get(c,[]),key=lambda x:len(x[0])):
        nb=norm(body); i=nb.find(nq)
        if i>=0: hit=(url,nb[i:i+len(nq)]); break
    if not hit: bad+=1; print("INTROUVABLE",q,c,quote[:70]); continue
    out.append({"question":q,"candidat":c,"score":s,"citation":quote,"niveau":niv,"source":{"url":hit[0],"consulte":"2026-11-16"},"note":note,"statut":"propose"})
print(len(out),"ok",bad,"introuvables")
json.dump(out,open('positions.json','w'),ensure_ascii=False,indent=1)
